def calculate_score(system: int, points: str) -> list:
    """
    Calculate the score of a series of ping-pong games based on the provided scoring system.

    :param system: The number of points required to win a game (either 11 or 21).
    :param points: A string of 'W' and 'L' characters denoting points won by the player and opponent.
    :return: A list of strings representing the score of each game.
    """
    games = []
    current_score = [0, 0]
    for p in points:
        if p == "W":
            current_score[0] += 1
        elif p == "L":
            current_score[1] += 1
        else:
            raise ValueError(f"Invalid point value '{p}', expected 'W' or 'L'.")
        if current_score[0] == system:
            games.append(f"{current_score[0]}:{current_score[1]}")
            current_score = [0, 0]
        elif current_score[1] == system:
            games.append(f"{current_score[1]}:{current_score[0]}")
            current_score = [0, 0]
    if current_score[0] or current_score[1]:
        games.append(f"{current_score[0]}:{current_score[1]}")
    return games

def catalan_number(n: int) -> int:

    if n == 0:
        return 1

    result = 0

    for i in range(n):
        result += catalan_number(i) * catalan_number(n-i-1)

    return result

